// TRAIL: the finished demo students play before they build their own (6.22-6.26).
//
// The core is exactly the chain's game: a path of squares made from one line of
// text, rows that snake back and forth, two tokens, a die, whose turn it is,
// squares that jump, slide and wait, and a winner. Online goes through
// multiplayer('versus', 2): the lobby bar above the game hosts and joins, every
// roll is sent, and onMove applies it on both computers after checking the seat
// and the roll. On one computer, L starts a game where whoever is at the keys
// rolls for both. On top: a title screen, a winner panel, a tumbling die,
// hopping tokens, textures and sound.
//
// Controls:  SPACE or click = roll   L = play on this computer   R = rematch

const TRACK = '....J....S..W..J.....S..W.J.S.F';   // one letter per square
const COLS = 10;
const SIZE = 56;
const TOP = 64;                  // the words live in the strip above the board
const W = COLS * SIZE;           // 560
const H = 380;
const NAMES = ['Pink', 'Blue'];
const INK = ['#ff7fb8', '#5ab4ff'];
const SKINS = ['playerPink', 'playerBlue'];
const TILE = { '.': 'sand', J: 'grass', S: 'ice', W: 'water', F: 'grass' };
const LABEL = { J: '+3', S: '-3', W: 'wait' };

let path;                        // path[i] is { x, y, kind }
let racers;                      // racers[p] is { at, waiting }
let side = 0;                    // whose turn: 0 Pink, 1 Blue
let lastRoll = 0;
let message = '';
let winner = -1;

let phase = 'title';             // 'title' | 'local' | 'online'
let log = [];                    // every move this room has sent, in order
let quiet = false;               // true while the log replays: no sound, no animation
let tokens = [];
let die;
let rolling = 0;                 // frames left on the die's tumble
let hops = [[], []];             // squares each token still hops through (display only)
let shown = [0, 0];              // the square each token is drawn on
let hopWait = 0;
let cheered = false;
let confetti = [];
let snd = {};

function setup() {
  new Canvas(W, H);
  randomSeed(Date.now());
  multiplayer('versus', 2);
  nextTurn();                    // turn is 1 until the lobby puts us in a room (see follow)
  online.onMove((m, who) => {
    follow();
    log.push({ m: m, who: who });
    if (phase === 'online') applyMove(m, who);
  });
  for (const name of ['dice', 'step', 'jump', 'whoosh', 'blip', 'win', 'select']) {
    snd[name] = loadSound(name);
  }
  path = makePath(TRACK);
  for (let i = 0; i < path.length; i++) {
    const s = new Sprite(path[i].x, path[i].y, SIZE - 6, SIZE - 6);
    s.collider = 'none';
    s.texture = TILE[path[i].kind];
    s.layer = 1;
    if (path[i].kind === 'J' || path[i].kind === 'F') {
      const t = new Sprite(path[i].x, path[i].y - 2, 34, 34);
      t.collider = 'none';
      t.texture = path[i].kind === 'J' ? 'spring' : 'flag';
      t.layer = 2;
    }
  }
  for (let p = 0; p < 2; p++) {
    const t = new Sprite(path[0].x, path[0].y, 34, 46);
    t.collider = 'none';
    t.texture = SKINS[p];
    t.layer = 5;
    tokens.push(t);
  }
  die = new Sprite(54, 334, 56, 56);
  die.collider = 'none';
  die.texture = 'num1';
  die.layer = 5;
  newGame();
}

// The track is text; the path is data made from it. Odd rows run right to left.
function makePath(track) {
  const squares = [];
  for (let i = 0; i < track.length; i++) {
    const r = floor(i / COLS);
    let c = i % COLS;
    if (r % 2 === 1) c = COLS - 1 - c;
    squares.push({ x: c * SIZE + SIZE / 2, y: TOP + r * SIZE + SIZE / 2, kind: track[i] });
  }
  return squares;
}

function newGame() {
  racers = [{ at: 0, waiting: false }, { at: 0, waiting: false }];
  side = 0;
  winner = -1;
  lastRoll = 0;
  message = 'Pink goes first';
  hops = [[], []];
  shown = [0, 0];
  rolling = 0;
  cheered = false;
  confetti = [];
}

// The lobby put this run in a room, or took it out: extras.js then sets turn
// back to 0 and replays that room's moves from the start, so the log starts
// again too. A full room is an online game, built from every move it has had.
function follow() {
  if (turn === 0) {
    nextTurn();
    log = [];
    if (phase === 'online') phase = 'title';
  }
  if (game.ready && phase !== 'online') {
    phase = 'online';
    quiet = true;
    newGame();
    for (const e of log) applyMove(e.m, e.who);
    quiet = false;
  }
}

function goodRoll(r) {
  return typeof r === 'number' && floor(r) === r && r >= 1 && r <= 6;
}

// The one place a move changes the game. Both computers run it for every move,
// so both ignore the same bad ones: the wrong seat, a roll that is no die.
function applyMove(m, who) {
  if (m === null || typeof m !== 'object') return;
  if (m.again === 1 && winner !== -1) { newGame(); return; }
  if (who !== side || winner !== -1 || !goodRoll(m.roll)) return;
  takeTurn(m.roll);
}

function takeTurn(r) {
  const p = racers[side];
  const from = p.at;
  const last = path.length - 1;
  lastRoll = r;
  p.at = min(p.at + r, last);
  const steps = [];
  for (let i = from + 1; i <= p.at; i++) steps.push({ at: i, how: 'step' });
  const kind = path[p.at].kind;
  message = NAMES[side] + ' rolled ' + r;
  if (kind === 'J') {
    const to = min(p.at + 3, last);
    steps.push({ at: to, how: 'jump' });
    p.at = to;
    message += ', sprang ahead 3';
  }
  if (kind === 'S') {
    const to = max(p.at - 3, 0);
    steps.push({ at: to, how: 'slide' });
    p.at = to;
    message += ', slid back 3';
  }
  if (kind === 'W') { p.waiting = true; message += ', stuck: waits a turn'; }
  if (!quiet) {
    rolling = 22;
    snd.dice.play();
    hops[side] = hops[side].concat(steps);
  } else {
    shown[side] = p.at;
  }
  if (p.at === last) {
    winner = side;
    message = NAMES[side] + ' reached the flag!';
    return;
  }
  passTurn();
}

function passTurn() {
  side = 1 - side;
  if (racers[side].waiting) {
    racers[side].waiting = false;
    message += '. ' + NAMES[side] + ' waits';
    side = 1 - side;
  }
}

function busy() {
  return rolling > 0 || hops[0].length > 0 || hops[1].length > 0;
}

function canRoll() {
  if (winner !== -1 || busy()) return false;
  if (phase === 'local') return true;
  return phase === 'online' && game.ready && online.seat === side;
}

function roll() {
  const r = floor(random(1, 7));
  if (phase === 'local') applyMove({ roll: r }, side);
  else online.send({ roll: r });       // applied in onMove, on both computers
}

function draw() {
  follow();
  background('#16241c');
  if (kb.presses('l') && !game.ready) {
    phase = 'local';
    newGame();
    snd.select.play();
  }
  const click = mouse.presses() && mouse.y > TOP && phase !== 'title';
  if ((kb.presses('space') || click) && canRoll()) roll();
  if (kb.presses('r') && winner !== -1 && !busy()) {
    if (phase === 'local') newGame();
    if (phase === 'online' && game.ready) online.send({ again: 1 });
  }
  animate();
  // the trail between the squares, so the snake reads as one path
  stroke('#6b4f2a');
  strokeWeight(10);
  for (let i = 1; i < path.length; i++) line(path[i - 1].x, path[i - 1].y, path[i].x, path[i].y);
  noStroke();
  fill('#0f1913');
  rect(0, TOP + 4 * SIZE, W, H - TOP - 4 * SIZE);
}

// Display only: the die tumbles, then each token hops one square at a time.
function animate() {
  if (rolling > 0) {
    rolling -= 1;
    die.texture = rolling > 0 ? 'num' + (1 + (floor(frameCount / 3) % 6)) : 'num' + lastRoll;
    die.rotation = rolling > 0 ? rolling * 9 : 0;
  } else {
    for (let p = 0; p < 2; p++) {
      if (hops[p].length === 0) continue;
      if (hopWait > 0) { hopWait -= 1; break; }
      const h = hops[p].shift();
      shown[p] = h.at;
      hopWait = h.how === 'step' ? 9 : 22;
      if (h.how === 'step') snd.step.play();
      if (h.how === 'jump') snd.jump.play();
      if (h.how === 'slide') snd.whoosh.play();
      if (hops[p].length === 0 && racers[p].waiting) snd.blip.play();
      break;
    }
  }
  if (lastRoll === 0) die.texture = 'num1';
  for (let p = 0; p < 2; p++) {
    const s = path[shown[p]];
    const same = shown[0] === shown[1];
    const tx = s.x + (same ? (p === 0 ? -11 : 11) : 0);
    const t = tokens[p];
    t.x += (tx - t.x) * 0.35;
    t.y += (s.y - 4 - t.y) * 0.35;
    t.scale = p === side && winner === -1 && phase !== 'title' ? 1 + 0.06 * sin(frameCount * 0.15) : 1;
  }
  if (winner !== -1 && !busy() && !cheered) {
    cheered = true;
    snd.win.play();
    for (let i = 0; i < 60; i++) {
      confetti.push({ x: random(0, W), y: random(-120, 0), v: random(1.5, 3.5), c: random([INK[0], INK[1], 'gold', 'white']) });
    }
  }
}

// text that never runs off the canvas: shrink it until it fits in maxW
function say(str, x, y, size, color, maxW) {
  str = String(str);
  const s = min(size, maxW / (str.length * 0.6));
  text(str, x + 1, y + 1, s, 'rgba(0,0,0,0.6)');
  text(str, x, y, s, color);
}

// What the online side is doing, in words (never a null).
function roomNote() {
  const st = online.status;
  if (st === 'waiting' && phase === 'online') return 'Your classmate left. Wait for them, or press L';
  if (st === 'waiting') return 'Room made: waiting for a classmate (L plays here meanwhile)';
  if (st === 'connecting') return 'Connecting to the room...';
  if (st === 'closed') return 'The room closed. Host a new one, or press L';
  if (st === 'error') return 'Online problem: ' + (online.error || 'try again');
  return '';
}

function statusLine() {
  if (phase === 'local') return 'One computer: you roll for both players. L: new game';
  if (online.status === 'ready') return 'Online: you are ' + (online.seat === 0 || online.seat === 1 ? NAMES[online.seat] : 'watching');
  return roomNote();
}

function drawTop() {
  textAlign('center');
  for (let i = 0; i < path.length; i++) {
    const k = path[i].kind;
    if (LABEL[k]) say(LABEL[k], path[i].x, path[i].y + 24, 12, 'white', SIZE - 8);
  }
  textAlign('left');
  for (let i = 0; i < path.length; i++) text('' + (i + 1), path[i].x - 25, path[i].y - 16, 10, 'rgba(0,0,0,0.55)');

  say('TRAIL', 14, 30, 24, 'gold', 120);
  say(message, 14, 54, 15, 'white', W - 28);
  if (phase !== 'title' && winner === -1) {
    textAlign('right');
    say(NAMES[side] + "'s turn", W - 14, 30, 18, INK[side], 260);
    textAlign('left');
  }

  // the strip under the board
  let prompt = '';
  if (winner !== -1) prompt = NAMES[winner] + ' wins!';
  else if (phase === 'local') prompt = NAMES[side] + ': press SPACE or click to roll';
  else if (phase === 'online' && game.ready && online.seat === side) prompt = 'Your turn: press SPACE or click to roll';
  else if (phase === 'online') prompt = 'Waiting for ' + NAMES[side] + ' to roll';
  say(prompt, 100, 322, 18, winner !== -1 ? INK[winner] : 'white', W - 112);
  say('+3 spring jumps ahead   -3 ice slides back   pond: wait a turn', 100, 346, 12, '#b9c7d8', W - 112);
  say(statusLine(), 100, 368, 12, 'gold', W - 112);

  if (phase === 'title') drawTitle();
  else if (winner !== -1 && !busy()) drawWinner();
}

const TITLE = [
  ['TRAIL', 88, 56, 'gold'],
  ['Roll the die, hop along the path, first to the flag wins.', 124, 15, 'white'],
  ['Springs jump you ahead, ice slides you back, a pond makes you wait.', 148, 13, '#b9c7d8'],
  ['Two ways to play', 196, 18, 'gold'],
  ['Online: press Host a room above the game, or Join', 226, 15, 'white'],
  ["a classmate's room from Open rooms. Host is Pink.", 248, 15, 'white'],
  ['One computer: press L. You roll for both players.', 282, 15, 'white'],
];

function drawTitle() {
  fill('rgba(8, 14, 10, 0.86)');
  rect(0, 0, W, H);
  textAlign('center');
  for (const t of TITLE) say(t[0], W / 2, t[1], t[2], t[3], W - 40);
  say(roomNote(), W / 2, 330, 14, 'gold', W - 40);
  textAlign('left');
}

function drawWinner() {
  for (const c of confetti) {
    c.y += c.v;
    if (c.y > H) c.y = -10;
    fill(c.c);
    rect(c.x + 6 * sin(c.y * 0.05), c.y, 6, 9);
  }
  fill('rgba(10, 12, 20, 0.82)');
  rect(W / 2 - 190, 110, 380, 150, 14);
  textAlign('center');
  say(NAMES[winner].toUpperCase() + ' WINS!', W / 2, 162, 40, INK[winner], 360);
  say('First to the flag, with a roll of ' + lastRoll + ' to finish', W / 2, 192, 14, 'white', 360);
  let again = 'L: play on this computer';
  if (phase === 'local') again = 'R: play again   L: new game';
  else if (game.ready) again = 'R: rematch (both screens start again)';
  say(again, W / 2, 230, 15, 'gold', 360);
  textAlign('left');
}

// CHECKERS: the finished demo students play before they build their own (6.27-6.32).
//
// The core is exactly the chain's game: a grid of letters built with two loops,
// a click turned into a row and a column, a step or a jump checked by one rule
// (moveKind), jumping again with the same piece, kings, and a win when the
// other side has no move. Online goes through multiplayer('versus', 2): the
// lobby bar above the game hosts and joins, every move is sent, and onMove runs
// the SAME rule check on both computers before it changes anything. On one
// computer, L starts a game where whoever is at the mouse plays both colours.
// On top: a title screen, a winner panel, legal squares shown, sliding pieces,
// a star on every king, the board turned round for Black, and sound.
//
// Controls:  click a piece, then a square   L = play on this computer   R = rematch

const N = 8;
const CELL = 50;
const TOP = 56;                 // the words live in the strip above the board
const W = N * CELL;             // 400
const H = TOP + N * CELL + 30;  // 486

let grid;                       // grid[r][c]: '' empty, 'r' red, 'b' black, 'R' and 'B' kings
let side = 'r';                 // whose turn: 'r' or 'b'
let picked = null;              // the selected piece, { r, c }
let chain = false;              // true while the piece that just jumped must jump again
let winner = '';
let message = '';
let lastMove = null;

let phase = 'title';            // 'title' | 'local' | 'online'
let log = [];                   // every move this room has sent, in order
let quiet = false;              // true while the log replays: no sound, no animation
let slides = [];                // pieces sliding into place (display only)
let stars = [];
let cheered = false;
let snd = {};

function setup() {
  new Canvas(W, H);
  multiplayer('versus', 2);
  nextTurn();                   // turn is 1 until the lobby puts us in a room (see follow)
  online.onMove((m, who) => {
    follow();
    log.push({ m: m, who: who });
    if (phase === 'online') applyMove(m, who);
  });
  for (const name of ['step', 'pop', 'crown', 'win', 'select', 'blip']) {
    snd[name] = loadSound(name);
  }
  for (let i = 0; i < 12; i++) {
    const s = new Sprite(-50, -50, 26, 26);
    s.collider = 'none';
    s.texture = 'star';
    s.layer = 5;
    s.visible = false;
    stars.push(s);
  }
  newGame();
}

function newGame() {
  grid = makeBoard();
  side = 'r';
  picked = null;
  chain = false;
  winner = '';
  lastMove = null;
  message = 'Red moves first';
  slides = [];
  cheered = false;
}

// Pieces sit on the dark squares, where (r + c) is odd.
function makeBoard() {
  const g = [];
  for (let r = 0; r < N; r++) {
    const row = [];
    for (let c = 0; c < N; c++) {
      let p = '';
      if ((r + c) % 2 === 1 && r < 3) p = 'b';
      if ((r + c) % 2 === 1 && r > 4) p = 'r';
      row.push(p);
    }
    g.push(row);
  }
  return g;
}

function colorOf(p) { return p.toLowerCase(); }
function isKing(p) { return p === 'R' || p === 'B'; }
function nameOf(t) { return t === 'r' ? 'Red' : 'Black'; }
function onBoard(r, c) { return r >= 0 && r < N && c >= 0 && c < N; }
function seatOf(t) { return t === 'r' ? 0 : 1; }      // the host plays red

// 'step', 'jump', or '' when the move is not allowed.
function moveKind(fr, fc, tr, tc) {
  if (!onBoard(fr, fc) || !onBoard(tr, tc)) return '';
  const p = grid[fr][fc];
  if (p === '' || colorOf(p) !== side || grid[tr][tc] !== '') return '';
  const dr = tr - fr;
  const dc = tc - fc;
  if (abs(dr) !== abs(dc)) return '';
  const ahead = side === 'r' ? dr < 0 : dr > 0;
  if (!ahead && !isKing(p)) return '';
  if (abs(dr) === 1) return 'step';
  if (abs(dr) === 2) {
    const mid = grid[fr + dr / 2][fc + dc / 2];
    if (mid !== '' && colorOf(mid) !== side) return 'jump';
  }
  return '';
}

function isLegal(fr, fc, tr, tc) {
  const kind = moveKind(fr, fc, tr, tc);
  if (kind === '') return false;
  if (chain) return kind === 'jump' && fr === picked.r && fc === picked.c;
  return true;
}

function canJumpFrom(r, c) {
  for (const dr of [-2, 2]) for (const dc of [-2, 2]) if (moveKind(r, c, r + dr, c + dc) === 'jump') return true;
  return false;
}

function hasAnyMove() {
  for (let r = 0; r < N; r++) for (let c = 0; c < N; c++) {
    for (const d of [-2, -1, 1, 2]) {
      if (moveKind(r, c, r + d, c + d) !== '' || moveKind(r, c, r + d, c - d) !== '') return true;
    }
  }
  return false;
}

// A move must be four whole numbers on the board; anything else is ignored.
function isSquare(r, c) { return typeof r === 'number' && typeof c === 'number' && floor(r) === r && floor(c) === c && onBoard(r, c); }
function goodMove(m) { return m !== null && typeof m === 'object' && isSquare(m.fr, m.fc) && isSquare(m.tr, m.tc); }

// The one place a move changes the game. Both computers run it for every move,
// with the same checks, so a wrong-seat or impossible move changes nothing anywhere.
function applyMove(m, who) {
  if (m === null || typeof m !== 'object') return;
  if (m.again === 1 && winner !== '') { newGame(); return; }
  if (goodMove(m) && who === seatOf(side) && winner === '' && isLegal(m.fr, m.fc, m.tr, m.tc)) {
    doMove(m.fr, m.fc, m.tr, m.tc);
  }
}

function doMove(fr, fc, tr, tc) {
  const kind = moveKind(fr, fc, tr, tc);
  const piece = grid[fr][fc];
  grid[tr][tc] = piece;
  grid[fr][fc] = '';
  if (kind === 'jump') {
    const mr = (fr + tr) / 2;
    const mc = (fc + tc) / 2;
    grid[mr][mc] = '';
  }
  const crowned = crown(tr, tc);
  lastMove = { fr: fr, fc: fc, tr: tr, tc: tc };
  if (!quiet) {
    slides.push({ fr: fr, fc: fc, tr: tr, tc: tc, t: 0 });
    if (crowned) snd.crown.play();
    else if (kind === 'jump') snd.pop.play();
    else snd.step.play();
  }
  if (kind === 'jump' && !crowned && canJumpFrom(tr, tc)) {
    picked = { r: tr, c: tc };
    chain = true;
    message = nameOf(side) + ' jumps again with the same piece!';
    return;
  }
  picked = null;
  chain = false;
  side = side === 'r' ? 'b' : 'r';
  message = crowned ? nameOf(side === 'r' ? 'b' : 'r') + ' has a new king' : nameOf(side) + "'s move";
  if (!hasAnyMove()) {
    winner = side === 'r' ? 'b' : 'r';
    message = nameOf(side) + ' has no move left';
  }
}

function crown(r, c) {
  const p = grid[r][c];
  if (p === 'r' && r === 0) { grid[r][c] = 'R'; return true; }
  if (p === 'b' && r === N - 1) { grid[r][c] = 'B'; return true; }
  return false;
}

function myMove() {
  if (winner !== '' || slides.length > 0) return false;
  if (phase === 'local') return true;
  return phase === 'online' && game.ready && online.seat === seatOf(side);
}

// Black's player sees the board turned round, so their own pieces are at the bottom.
function flipped() { return phase === 'online' && online.seat === 1; }
function screenOf(r, c) {
  const f = flipped();
  const rr = f ? N - 1 - r : r;
  const cc = f ? N - 1 - c : c;
  return { x: cc * CELL + CELL / 2, y: TOP + rr * CELL + CELL / 2 };
}

// The lobby put this run in a room, or took it out: extras.js then sets turn
// back to 0 and replays that room's moves from the start, so the log starts
// again too. A full room is an online game, built from every move it has had.
function follow() {
  if (turn === 0) {
    nextTurn();
    log = [];
    if (phase === 'online') phase = 'title';
  }
  if (game.ready && phase !== 'online') {
    phase = 'online';
    quiet = true;
    newGame();
    for (const e of log) applyMove(e.m, e.who);
    quiet = false;
  }
}

function draw() {
  follow();
  background('#1b1d2a');
  if (kb.presses('l') && !game.ready) {
    phase = 'local';
    newGame();
    snd.select.play();
  }
  if (kb.presses('r') && winner !== '') {
    if (phase === 'local') newGame();
    if (phase === 'online' && game.ready) online.send({ again: 1 });
  }
  if (mouse.presses() && phase !== 'title' && myMove()) clickAt(mouse.x, mouse.y);
  drawBoard();
  drawPieces();
}

function clickAt(x, y) {
  let c = floor(x / CELL);
  let r = floor((y - TOP) / CELL);
  if (flipped()) { r = N - 1 - r; c = N - 1 - c; }
  if (!onBoard(r, c)) return;
  const p = grid[r][c];
  if (!chain && p !== '' && colorOf(p) === side) {
    picked = { r: r, c: c };
    snd.blip.play();
    return;
  }
  if (picked !== null && isLegal(picked.r, picked.c, r, c)) {
    const m = { fr: picked.r, fc: picked.c, tr: r, tc: c };
    if (phase === 'local') applyMove(m, seatOf(side));
    else online.send(m);        // applied in onMove, on both computers
  }
}

function drawBoard() {
  noStroke();
  for (let r = 0; r < N; r++) for (let c = 0; c < N; c++) {
    const s = screenOf(r, c);
    fill((r + c) % 2 === 1 ? '#7a5a40' : '#ead9b6');
    rect(s.x - CELL / 2, s.y - CELL / 2, CELL, CELL);
  }
  if (lastMove !== null) {
    fill('rgba(80, 170, 255, 0.42)');
    for (const sq of [screenOf(lastMove.fr, lastMove.fc), screenOf(lastMove.tr, lastMove.tc)]) rect(sq.x - CELL / 2, sq.y - CELL / 2, CELL, CELL);
  }
  if (picked !== null && winner === '') {
    const s = screenOf(picked.r, picked.c);
    fill('rgba(255, 215, 0, 0.5)');
    rect(s.x - CELL / 2, s.y - CELL / 2, CELL, CELL);
    if (myMove()) {
      for (const d of [-2, -1, 1, 2]) for (const e of [-1, 1]) {
        const tr = picked.r + d;
        const tc = picked.c + d * e;
        if (onBoard(tr, tc) && isLegal(picked.r, picked.c, tr, tc)) {
          const q = screenOf(tr, tc);
          fill('rgba(255, 215, 0, 0.75)');
          circle(q.x, q.y, 16);
        }
      }
    }
  }
}

function drawPiece(p, x, y) {
  const red = colorOf(p) === 'r';
  fill(red ? '#ffd2c8' : '#9a9a9a');
  circle(x, y + 2, CELL * 0.8);
  fill(red ? '#dc463c' : '#222226');
  circle(x, y, CELL * 0.72);
  fill(red ? '#f06e5f' : '#46464e');
  circle(x, y, CELL * 0.5);
}

function drawPieces() {
  const moving = slides.length > 0 ? slides[0] : null;
  if (moving !== null) moving.t = min(moving.t + 0.16, 1);
  let k = 0;
  for (let r = 0; r < N; r++) for (let c = 0; c < N; c++) {
    const p = grid[r][c];
    if (p === '') continue;
    let s = screenOf(r, c);
    if (moving !== null && moving.tr === r && moving.tc === c) {
      const a = screenOf(moving.fr, moving.fc);
      const t = moving.t;
      s = { x: a.x + (s.x - a.x) * t, y: a.y + (s.y - a.y) * t - sin(t * PI) * 14 };
    }
    drawPiece(p, s.x, s.y);
    if (isKing(p) && k < stars.length) {
      stars[k].x = s.x;
      stars[k].y = s.y;
      stars[k].visible = true;
      k += 1;
    }
  }
  for (; k < stars.length; k++) stars[k].visible = false;
  if (moving !== null && moving.t >= 1) slides.shift();
}

function say(str, x, y, size, color, maxW) {
  str = String(str);
  const s = min(size, maxW / (str.length * 0.6));
  text(str, x + 1, y + 1, s, 'rgba(0,0,0,0.6)');
  text(str, x, y, s, color);
}

function count(t) {
  let n = 0;
  for (const row of grid) for (const p of row) if (p !== '' && colorOf(p) === t) n += 1;
  return n;
}

// What the online side is doing, in words (never a null).
function roomNote() {
